// Regenerate packages/core/src/api/schema.ts from the backend's OpenAPI spec.
// Run after any backend schema change: `pnpm gen:api`. The generated file is committed
// so frontend typechecks never need a running backend.
import { execFileSync } from "node:child_process";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import openapiTS, { astToString } from "openapi-typescript";

const root = resolve(import.meta.dirname, "..");
const py = join(root, "backend", ".venv", "bin", "python");
const spec = execFileSync(py, ["-c", "import json; from app.main import app; print(json.dumps(app.openapi()))"], {
  cwd: join(root, "backend"),
  env: { ...process.env, GAZYAR_DATABASE_URL: `sqlite:///${join(mkdtempSync(join(tmpdir(), "gz-")), "spec.db")}` },
  maxBuffer: 64 * 1024 * 1024,
}).toString();
const ast = await openapiTS(JSON.parse(spec), { alphabetize: true });
const header = "// GENERATED by scripts/gen-api.mjs from the FastAPI OpenAPI spec — do not edit by hand.\n\n";
const out = join(root, "packages", "core", "src", "api", "schema.ts");
writeFileSync(out, header + astToString(ast));
console.log("wrote", out);
